# AUTO-GENERATED by Claude Code
# Purpose: `ToolCallLog`, an agent capability that logs each tool call as one timed 'tool'
# record and tags every record made during it (start.gg requests, HTTP fetches) with the
# call's `tool_call_id`, so an app can link those records back to the call (eg its chat row).
# Usage: Agent(..., capabilities=[ToolCallLog(), ...]) (ds.ai.agent does). Records are off
# until an app turns them on (ds.util.logging.enable_call_logs).
# ---------------------------------------------------------------------------
from __future__ import annotations

from dataclasses import dataclass
from typing import TYPE_CHECKING, Any

from pydantic_ai.capabilities import AbstractCapability

from ds.util.logging import log_call, logger

if TYPE_CHECKING:
    from pydantic_ai import RunContext
    from pydantic_ai.capabilities.abstract import ValidatedToolArgs, WrapToolExecuteHandler
    from pydantic_ai.messages import ToolCallPart
    from pydantic_ai.tools import ToolDefinition

MAX_ARGS_CHARS = 300  # tool arguments kept in the record


@dataclass
class ToolCallLog(AbstractCapability[Any]):
    """One 'tool' record per tool call (name, arguments, time, error)

    Also puts `tool_call_id` on every record made while the tool runs (contextvars follow the
    tool into its worker thread).
    """

    async def wrap_tool_execute(  # pydantic-ai's hook signature
        self,
        ctx: RunContext[Any],  # noqa: ARG002  # part of the hook's signature
        *,
        call: ToolCallPart,
        tool_def: ToolDefinition,  # noqa: ARG002
        args: ValidatedToolArgs,
        handler: WrapToolExecuteHandler,
    ) -> Any:
        """Run the tool inside a 'tool' record, with its call id in the log context"""
        arguments = call.args_as_json_str()
        if len(arguments) > MAX_ARGS_CHARS:
            arguments = arguments[:MAX_ARGS_CHARS] + "…"
        with (
            logger.contextualize(tool_call_id=call.tool_call_id),
            log_call("tool", "smash-agent", name=call.tool_name, args=arguments),
        ):
            return await handler(args)
